## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/rectalCancerLogic.ts`

```typescript
/**
 * Rectal Cancer Clinical Compass™ — Decision Support Logic
 * Based on:
 * - NCCN Guidelines® Rectal Cancer v3.2024 (PMID: 39151454)
 * - ESMO Living Guideline: Localised Rectal Cancer v1.0 2025 (PMID: 40412553)
 * - ASCO Guideline Clinical Insights 2025 (PMID: 39236282)
 * Key trials: RAPIDO, PRODIGE 23, OPRA, PROSPECT, TRIGGER
 */

// ─── Input Types ─────────────────────────────────────────────────────────────

export type TStage = "T1" | "T2" | "T3" | "T4a" | "T4b";
export type NStage = "N0" | "N1" | "N2";
export type MStage = "M0" | "M1";
export type TumorLocation = "upper" | "mid" | "lower"; // upper: >10cm, mid: 5-10cm, lower: <5cm from anal verge
export type MRFStatus = "clear" | "threatened" | "involved"; // MRF = mesorectal fascia
export type EMVIStatus = "negative" | "positive" | "unknown";
export type SurgicalFitness = "fit" | "borderline" | "unfit";
export type ResponseAssessment = "cCR" | "near_cCR" | "partial" | "no_response" | "not_assessed";
export type PatientPreference = "organ_preservation" | "definitive_surgery" | "no_preference";

export interface RectalCancerInput {
  // Staging
  tStage: TStage;
  nStage: NStage;
  mStage: MStage;
  // Tumor characteristics
  tumorLocation: TumorLocation;
  mrfStatus: MRFStatus;
  emviStatus: EMVIStatus;
  tumorSize: number; // cm
  // Patient factors
  age: number;
  ecogPS: 0 | 1 | 2 | 3 | 4;
  surgicalFitness: SurgicalFitness;
  // Treatment history
  priorPelvicRT: boolean;
  priorChemo: boolean;
  // Response assessment (after neoadjuvant)
  responseAssessment: ResponseAssessment;
  // Patient preference
  patientPreference: PatientPreference;
  // Comorbidities
  ibd: boolean; // inflammatory bowel disease
  msi_mmr: "MSI-H" | "MSS" | "unknown"; // microsatellite instability
}

// ─── Output Types ─────────────────────────────────────────────────────────────

export type TreatmentStrategy =
  | "tnt_preferred"
  | "tnt_alternative"
  | "upfront_surgery"
  | "watch_and_wait"
  | "palliative"
  | "immunotherapy_first"
  | "multidisciplinary_discussion";

export type UrgencyLevel = "routine" | "urgent" | "emergent";

export interface RectalCancerRecommendation {
  strategy: TreatmentStrategy;
  strategyLabel: string;
  urgency: UrgencyLevel;
  // TNT details
  tntRegimen?: "short_course_rt_chemo" | "long_course_crt_chemo" | "induction_chemo_crt";
  tntRegimenLabel?: string;
  // Surgical details
  surgicalApproach?: "lar" | "apr" | "tme" | "local_excision" | "transanal_tme";
  surgicalApproachLabel?: string;
  // Watch-and-wait
  wwEligible: boolean;
  wwCriteria?: string[];
  // Organ preservation score
  organPreservationScore: number; // 0-100
  organPreservationLabel: string;
  // Key warnings
  keyWarnings: string[];
  // Next steps
  nextSteps: string[];
  // Rationale
  rationale: string;
  // Evidence level
  evidenceLevel: "Category 1" | "Category 2A" | "Category 2B" | "Category 3";
  guidelineSource: string;
}

// ─── Helper Functions ─────────────────────────────────────────────────────────

export function classifyDisease(input: RectalCancerInput): string {
  const { tStage, nStage, mStage } = input;
  if (mStage === "M1") return "metastatic";
  if (tStage === "T1" && nStage === "N0") return "early";
  if (tStage === "T2" && nStage === "N0") return "early_t2";
  if ((tStage === "T3" || tStage === "T4a") && nStage === "N0") return "locally_advanced_low_risk";
  if (nStage !== "N0" || tStage === "T4b" || input.mrfStatus !== "clear") return "locally_advanced_high_risk";
  return "locally_advanced_intermediate";
}

export function isTNTCandidate(input: RectalCancerInput): boolean {
  const { tStage, nStage, mrfStatus, emviStatus, tumorLocation, mStage } = input;
  if (mStage === "M1") return false;
  if (input.priorPelvicRT) return false;
  // High-risk features per RAPIDO/PRODIGE 23 criteria
  const highRiskFeatures = [
    tStage === "T4a" || tStage === "T4b",
    nStage === "N2",
    mrfStatus === "threatened" || mrfStatus === "involved",
    emviStatus === "positive",
    tumorLocation === "lower" && nStage !== "N0",
  ].filter(Boolean).length;
  // T3N0 with clear MRF — TNT is an option but not required
  if (tStage === "T3" && nStage === "N0" && mrfStatus === "clear") return true;
  return highRiskFeatures >= 1;
}

export function isWatchAndWaitEligible(input: RectalCancerInput): boolean {
  const { responseAssessment, mStage, surgicalFitness, priorPelvicRT } = input;
  if (mStage === "M1") return false;
  if (priorPelvicRT) return false;
  return (
    responseAssessment === "cCR" ||
    (responseAssessment === "near_cCR" && surgicalFitness === "unfit") ||
    (responseAssessment === "near_cCR" && input.patientPreference === "organ_preservation")
  );
}

export function selectTNTRegimen(input: RectalCancerInput): {
  regimen: "short_course_rt_chemo" | "long_course_crt_chemo" | "induction_chemo_crt";
  label: string;
  rationale: string;
} {
  const { mrfStatus, tStage, emviStatus, tumorLocation } = input;
  // RAPIDO regimen: short-course RT → consolidation chemo (preferred for high-risk)
  if (mrfStatus === "involved" || tStage === "T4b" || emviStatus === "positive") {
    return {
      regimen: "short_course_rt_chemo",
      label: "Short-course RT (5×5 Gy) → CAPOX/FOLFOX × 6 cycles → TME (RAPIDO regimen)",
      rationale: "RAPIDO trial: superior pCR (28% vs 14%) and 3-year disease-free survival (30.4% vs 27.7%) vs standard CRT for high-risk locally advanced rectal cancer.",
    };
  }
  // PRODIGE 23 regimen: induction FOLFIRINOX → CRT → surgery
  if (tStage === "T3" || tStage === "T4a") {
    return {
      regimen: "induction_chemo_crt",
      label: "Induction mFOLFIRINOX × 6 cycles → CRT → TME (PRODIGE 23 regimen)",
      rationale: "PRODIGE 23 trial: improved 3-year DFS (75.7% vs 68.5%) and pCR rate (27.5% vs 11.7%) with induction FOLFIRINOX before CRT.",
    };
  }
  // Standard long-course CRT + consolidation
  return {
    regimen: "long_course_crt_chemo",
    label: "Long-course CRT (45-50.4 Gy + capecitabine) → consolidation CAPOX × 2-3 cycles → TME",
    rationale: "OPRA trial: consolidation chemotherapy after CRT increases organ preservation rates (58% W&W at 3 years for cCR patients).",
  };
}

export function calculateOrganPreservationScore(input: RectalCancerInput): number {
  let score = 50; // baseline
  // Favorable factors
  if (input.tumorLocation === "lower") score += 15; // lower tumors → APR avoided
  if (input.patientPreference === "organ_preservation") score += 10;
  if (input.responseAssessment === "cCR") score += 25;
  if (input.responseAssessment === "near_cCR") score += 15;
  if (input.tStage === "T1" || input.tStage === "T2") score += 10;
  if (input.nStage === "N0") score += 5;
  // Unfavorable factors
  if (input.tStage === "T4b") score -= 20;
  if (input.mrfStatus === "involved") score -= 15;
  if (input.nStage === "N2") score -= 10;
  if (input.responseAssessment === "no_response") score -= 30;
  if (input.priorPelvicRT) score -= 20;
  if (input.ibd) score -= 10;
  return Math.max(0, Math.min(100, score));
}

// ─── Main Assessment Function ─────────────────────────────────────────────────

export function assessRectalCancer(input: RectalCancerInput): RectalCancerRecommendation {
  const warnings: string[] = [];
  const nextSteps: string[] = [];
  const diseaseClass = classifyDisease(input);
  const organScore = calculateOrganPreservationScore(input);

  // ── Metastatic disease ──
  if (input.mStage === "M1") {
    // MSI-H/dMMR: immunotherapy first
    if (input.msi_mmr === "MSI-H") {
      return {
        strategy: "immunotherapy_first",
        strategyLabel: "Immunotherapy-First (Pembrolizumab)",
        urgency: "routine",
        wwEligible: false,
        organPreservationScore: organScore,
        organPreservationLabel: "Not applicable (metastatic disease)",
        keyWarnings: ["MSI-H/dMMR metastatic rectal cancer — pembrolizumab first-line per KEYNOTE-177"],
        nextSteps: [
          "Pembrolizumab 200 mg Q3W (KEYNOTE-177 regimen)",
          "Multidisciplinary tumor board discussion",
          "Consider conversion resection if response achieved",
        ],
        rationale: "KEYNOTE-177: pembrolizumab superior to chemotherapy as first-line for MSI-H/dMMR mCRC (PFS HR 0.60, OS HR 0.74).",
        evidenceLevel: "Category 1",
        guidelineSource: "NCCN Rectal Cancer v3.2024; ESMO 2025",
      };
    }
    return {
      strategy: "palliative",
      strategyLabel: "Systemic Therapy (Palliative Intent)",
      urgency: "routine",
      wwEligible: false,
      organPreservationScore: 0,
      organPreservationLabel: "Not applicable (metastatic disease)",
      keyWarnings: ["Metastatic disease — curative resection not indicated unless oligometastatic with resectable disease"],
      nextSteps: [
        "FOLFOX/FOLFIRI + bevacizumab or cetuximab (RAS/BRAF status)",
        "Consider resection of primary if symptomatic obstruction/bleeding",
        "Multidisciplinary tumor board discussion",
        "Assess for oligometastatic resection candidacy",
      ],
      rationale: "Systemic therapy is standard for metastatic rectal cancer. Oligometastatic disease may be considered for curative resection after MDT discussion.",
      evidenceLevel: "Category 1",
      guidelineSource: "NCCN Rectal Cancer v3.2024",
    };
  }

  // ── Early stage (T1N0) — local excision ──
  if (input.tStage === "T1" && input.nStage === "N0") {
    const wwEligible = input.responseAssessment === "cCR";
    return {
      strategy: "upfront_surgery",
      strategyLabel: "Local Excision (TEM/TAMIS) or Low Anterior Resection",
      urgency: "routine",
      surgicalApproach: "local_excision",
      surgicalApproachLabel: "Transanal Endoscopic Microsurgery (TEM) or TAMIS for T1N0 <3 cm, favorable histology",
      wwEligible,
      wwCriteria: wwEligible ? ["cCR after neoadjuvant therapy"] : undefined,
      organPreservationScore: organScore,
      organPreservationLabel: organScore >= 70 ? "High — organ preservation likely achievable" : "Moderate",
      keyWarnings: [
        "Ensure no high-risk features: sm3 invasion, LVI, poor differentiation — if present, proceed to TME",
        input.tumorLocation === "lower"
          ? "Lower rectal T1N0: TEM/TAMIS preferred to avoid permanent colostomy"
          : "",
      ].filter(Boolean),
      nextSteps: [
        "Endorectal ultrasound or MRI for precise T-staging",
        "TEM/TAMIS for T1N0 <3 cm with favorable histology",
        "If high-risk features on pathology: completion TME",
        "Surveillance: MRI + endoscopy Q3-6 months × 2 years",
      ],
      rationale: "T1N0 rectal cancer: local excision (TEM/TAMIS) is appropriate for lesions <3 cm without high-risk features. TME required for sm3, LVI, or poor differentiation.",
      evidenceLevel: "Category 2A",
      guidelineSource: "NCCN Rectal Cancer v3.2024; ESMO 2025",
    };
  }

  // ── T2N0 — surgery vs short-course RT + surgery ──
  if (input.tStage === "T2" && input.nStage === "N0" && input.mrfStatus === "clear") {
    const wwEligible = isWatchAndWaitEligible(input);
    const tntCandidate = input.tumorLocation === "lower" && input.patientPreference === "organ_preservation";
    return {
      strategy: tntCandidate ? "tnt_alternative" : "upfront_surgery",
      strategyLabel: tntCandidate
        ? "Neoadjuvant CRT → Assess Response → Surgery or W&W"
        : "Total Mesorectal Excision (TME)",
      urgency: "routine",
      surgicalApproach: input.tumorLocation === "lower" ? "apr" : "lar",
      surgicalApproachLabel: input.tumorLocation === "lower"
        ? "Abdominoperineal Resection (APR) — unless organ preservation achieved"
        : "Low Anterior Resection (LAR) with TME",
      wwEligible,
      wwCriteria: wwEligible ? ["cCR after neoadjuvant therapy", "Patient preference for organ preservation", "Strict surveillance protocol"] : undefined,
      organPreservationScore: organScore,
      organPreservationLabel: organScore >= 60 ? "Moderate-High — consider neoadjuvant if organ preservation desired" : "Moderate",
      keyWarnings: [
        input.tumorLocation === "lower"
          ? "Lower T2N0: discuss organ preservation options — neoadjuvant CRT may allow W&W if cCR achieved"
          : "",
        "Ensure accurate MRI staging before treatment decision",
      ].filter(Boolean),
      nextSteps: [
        "High-resolution MRI pelvis for precise staging",
        tntCandidate
          ? "Neoadjuvant CRT (50.4 Gy + capecitabine) → response assessment MRI at 8-12 weeks"
          : "Upfront TME with nerve-sparing technique",
        "Multidisciplinary tumor board discussion",
        "Discuss sphincter preservation vs permanent colostomy with patient",
      ],
      rationale: "T2N0 rectal cancer: upfront TME is standard. For lower rectal T2N0 with patient preference for organ preservation, neoadjuvant CRT with W&W after cCR is an option per OPRA trial.",
      evidenceLevel: "Category 2A",
      guidelineSource: "NCCN Rectal Cancer v3.2024; ESMO 2025",
    };
  }

  // ── Locally advanced — TNT vs standard CRT ──
  const tntCandidate = isTNTCandidate(input);
  const wwEligible = isWatchAndWaitEligible(input);
  const tntRegimen = selectTNTRegimen(input);

  if (input.priorPelvicRT) {
    warnings.push("Prior pelvic RT: re-irradiation carries significant toxicity risk — limit dose and discuss with radiation oncology");
  }
  if (input.ibd) {
    warnings.push("IBD: increased radiation toxicity risk — consider surgery-first approach");
  }
  if (input.msi_mmr === "MSI-H") {
    warnings.push("MSI-H/dMMR: consider immunotherapy (pembrolizumab) as neoadjuvant — NICHE-2 trial shows high pCR rates");
  }
  if (input.tStage === "T4b") {
    warnings.push("T4b disease: multivisceral resection likely required — ensure surgical team experienced in en-bloc resection");
  }
  if (input.surgicalFitness === "unfit") {
    warnings.push("Patient unfit for surgery: consider definitive CRT or watch-and-wait after TNT if cCR achieved");
  }
  if (input.mrfStatus === "involved") {
    warnings.push("MRF involvement: R0 resection may require extended surgery — TNT to downstage is strongly recommended");
  }

  nextSteps.push("High-resolution MRI pelvis (3T preferred) for baseline staging");
  nextSteps.push("Multidisciplinary tumor board discussion (surgery, radiation, medical oncology, radiology)");
  if (tntCandidate) {
    nextSteps.push(`Initiate TNT: ${tntRegimen.label}`);
    nextSteps.push("Response assessment MRI at 8-12 weeks after completion of TNT");
    if (wwEligible) {
      nextSteps.push("If cCR confirmed: discuss watch-and-wait with patient — strict surveillance protocol required");
    } else {
      nextSteps.push("Plan TME surgery 6-12 weeks after completion of TNT");
    }
  } else {
    nextSteps.push("Standard long-course CRT (45-50.4 Gy + capecitabine)");
    nextSteps.push("Surgery (TME) 6-8 weeks after CRT completion");
  }
  nextSteps.push("Adjuvant chemotherapy discussion based on pathologic response");

  const organLabel =
    organScore >= 70 ? "High — organ preservation likely achievable with cCR" :
    organScore >= 50 ? "Moderate — organ preservation possible, depends on response" :
    organScore >= 30 ? "Low-Moderate — surgery likely required" :
    "Low — surgery strongly recommended";

  return {
    strategy: tntCandidate ? "tnt_preferred" : "tnt_alternative",
    strategyLabel: tntCandidate
      ? "Total Neoadjuvant Therapy (TNT) — Preferred"
      : "Standard Neoadjuvant CRT → TME",
    urgency: input.tStage === "T4b" && input.mrfStatus === "involved" ? "urgent" : "routine",
    tntRegimen: tntCandidate ? tntRegimen.regimen : undefined,
    tntRegimenLabel: tntCandidate ? tntRegimen.label : undefined,
    surgicalApproach: input.tumorLocation === "lower" ? "apr" : "lar",
    surgicalApproachLabel: input.tumorLocation === "lower"
      ? "Abdominoperineal Resection (APR) or intersphincteric resection"
      : "Low Anterior Resection (LAR) with TME",
    wwEligible,
    wwCriteria: wwEligible
      ? [
          "Clinical complete response (cCR) confirmed on MRI + endoscopy",
          "No residual tumor on DRE",
          "Patient willing and able to comply with strict surveillance",
          "Surveillance: MRI + endoscopy Q3 months × 2 years, then Q6 months × 3 years",
        ]
      : undefined,
    organPreservationScore: organScore,
    organPreservationLabel: organLabel,
    keyWarnings: warnings,
    nextSteps,
    rationale: tntCandidate
      ? `TNT preferred for high-risk locally advanced rectal cancer. ${tntRegimen.rationale}`
      : "Standard neoadjuvant CRT followed by TME for intermediate-risk locally advanced rectal cancer.",
    evidenceLevel: tntCandidate ? "Category 1" : "Category 2A",
    guidelineSource: "NCCN Rectal Cancer v3.2024 (PMID: 39151454); ESMO Living Guideline 2025 (PMID: 40412553); ASCO 2025 (PMID: 39236282)",
  };
}

// ─── Utility Functions ─────────────────────────────────────────────────────────

export function getStrategyColor(strategy: TreatmentStrategy): string {
  switch (strategy) {
    case "tnt_preferred": return "bg-emerald-900/40 border-emerald-600 text-emerald-300";
    case "tnt_alternative": return "bg-blue-900/40 border-blue-600 text-blue-300";
    case "upfront_surgery": return "bg-violet-900/40 border-violet-600 text-violet-300";
    case "watch_and_wait": return "bg-teal-900/40 border-teal-600 text-teal-300";
    case "palliative": return "bg-slate-800/50 border-slate-600 text-slate-400";
    case "immunotherapy_first": return "bg-amber-900/40 border-amber-600 text-amber-300";
    case "multidisciplinary_discussion": return "bg-orange-900/40 border-orange-600 text-orange-300";
    default: return "bg-slate-800/50 border-slate-600 text-slate-400";
  }
}

export function getOrganPreservationColor(score: number): string {
  if (score >= 70) return "text-emerald-400";
  if (score >= 50) return "text-yellow-400";
  if (score >= 30) return "text-orange-400";
  return "text-red-400";
}
